  $positions=[];$sourceRows=$payload['sources']??[];abort_unless(is_array($sourceRows)&&count($sourceRows)>0,409);$sorted=$sourceRows;usort($sorted,fn($a,$b)=>strcmp((string)$a['position_uuid'],(string)$b['position_uuid']));
