  $locked=IntegrationOrganizationMapping::query()->whereKey($mapping->id)->lockForUpdate()->firstOrFail();abort_unless($locked->status==='verified'&&$locked->activation_state==='active'&&(int)$locked->solastock_organization_id===$org&&(int)$locked->finance_organization_id===(int)$mapping->finance_organization_id&&$locked->mapping_uuid===$mapping->mapping_uuid&&(int)$locked->central_client_id===(int)$mapping->central_client_id&&(int)$locked->central_organization_id===$org&&$locked->tenant_database_identity===$db->getDatabaseName(),409);
  $sources=[];$total='0';$seen=[];$quantityByLine=[];usort($sourceRows,fn($a,$b)=>[(int)$a['receipt_id'],(int)$a['receipt_line_id']]<=>[(int)$b['receipt_id'],(int)$b['receipt_line_id']]);
