   $factor=(string)($line->unit_conversion_factor?:'1');$quantity=Decimal::mul((string)$source['quantity'],$factor,8);abort_unless(Decimal::gt($quantity,'0')&&!Decimal::gt($quantity,(string)$line->accepted_qty)&&!Decimal::lt((string)$source['delta_base'],'0'),409);
   $quantityByLine[$line->id]=Decimal::add($quantityByLine[$line->id]??'0',$quantity,8);abort_unless(!Decimal::gt($quantityByLine[$line->id],(string)$line->accepted_qty),409);
