  }
  abort_unless(Decimal::cmp($total,(string)$payload['amount_base'],8)===0,409);
  if($action==='prepare')abort_unless(!$op->journal_entry_id&&in_array($op->state,['prepared','quoted'],true),409);
  if($action==='apply'){abort_unless((int)$op->journal_entry_id>0&&(int)$cost->journal_entry_id===(int)$op->journal_entry_id&&(int)($proof['landed_cost_journal_id']??0)===(int)$op->journal_entry_id&&hash_equals((string)$op->plan_fingerprint,(string)($proof['plan_fingerprint']??'')),409);$costJournal=$db->table('journal_entries')->where('organization_id',$mapping->finance_organization_id)->where('id',$op->journal_entry_id)->where('source','AP-LANDED-COST')->where('source_type','App\\Models\\LandedCost')->where('source_id',$cost->id)->lockForUpdate()->first();self::activeJournal($costJournal);}
  // Reverse/release cannot be inferred from a forward operation. Canonical lifecycle intent is mandatory.
  if(in_array($action,['reverse','release'],true))abort(409,'The native landed-cost lifecycle intent is not available.');
  $settings=$db->table('organizations')->where('id',$mapping->finance_organization_id)->first();$scale=(int)($settings->money_scale??2);abort_unless($scale>=0&&$scale<=6,409);
  return new self($payload,$sources,$proof,$org,(int)$mapping->finance_organization_id,$scale);
 }
 private static function activeJournal(?object $journal):void{abort_unless($journal&&$journal->status==='posted'&&!empty($journal->posted_at)&&empty($journal->voided_at)&&empty($journal->deleted_at),409);}
 public function operationUuid():string{return$this->facts['operation_uuid'];} public function organizationId():int{return$this->stockOrg;} public function financeOrganizationId():int{return$this->financeOrg;} public function mappingUuid():string{return$this->facts['organization_mapping_uuid'];}
